-- MySQL 8.0+ initial schema. UUID values are generated by the application.
SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE users (
  id CHAR(36) NOT NULL,
  email VARCHAR(320) NOT NULL,
  display_name VARCHAR(128) NOT NULL,
  password_hash VARCHAR(255) NULL,
  platform_role ENUM('admin', 'member', 'auditor') NOT NULL DEFAULT 'member',
  status ENUM('active', 'disabled') NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_users_email (email),
  KEY idx_users_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE business_systems (
  id CHAR(36) NOT NULL,
  system_key VARCHAR(64) NOT NULL,
  name VARCHAR(128) NOT NULL,
  description TEXT NULL,
  status ENUM('active', 'archived') NOT NULL DEFAULT 'active',
  created_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_business_systems_key (system_key),
  KEY idx_business_systems_created_by (created_by),
  CONSTRAINT fk_business_systems_created_by FOREIGN KEY (created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE system_members (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  role ENUM('owner', 'maintainer', 'reviewer', 'runner', 'viewer') NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_system_members_system_user (system_id, user_id),
  KEY idx_system_members_user (user_id, system_id),
  CONSTRAINT fk_system_members_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_system_members_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE code_sources (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  name VARCHAR(128) NOT NULL,
  source_type ENUM('git', 'local') NOT NULL,
  repository_url VARCHAR(1024) NULL,
  local_path VARCHAR(1024) NULL,
  default_ref VARCHAR(255) NULL,
  include_paths JSON NULL,
  exclude_paths JSON NULL,
  credential_ref VARCHAR(255) NULL,
  status ENUM('active', 'disabled') NOT NULL DEFAULT 'active',
  created_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_code_sources_system_name (system_id, name),
  UNIQUE KEY uk_code_sources_system_id_id (system_id, id),
  KEY idx_code_sources_created_by (created_by),
  CONSTRAINT fk_code_sources_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_code_sources_created_by FOREIGN KEY (created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scan_runs (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  code_source_id CHAR(36) NOT NULL,
  source_ref VARCHAR(255) NULL,
  source_commit VARCHAR(128) NULL,
  language VARCHAR(32) NULL,
  framework VARCHAR(64) NULL,
  status ENUM('queued', 'running', 'succeeded', 'failed', 'cancelled') NOT NULL DEFAULT 'queued',
  config JSON NULL,
  summary JSON NULL,
  error_message TEXT NULL,
  requested_by CHAR(36) NOT NULL,
  started_at DATETIME(3) NULL,
  finished_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scan_runs_system_id_id (system_id, id),
  KEY idx_scan_runs_system_status_created (system_id, status, created_at),
  KEY idx_scan_runs_source_created (system_id, code_source_id, created_at),
  KEY idx_scan_runs_requested_by (requested_by),
  CONSTRAINT fk_scan_runs_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scan_runs_source FOREIGN KEY (system_id, code_source_id) REFERENCES code_sources (system_id, id),
  CONSTRAINT fk_scan_runs_requested_by FOREIGN KEY (requested_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE api_operations (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  scan_run_id CHAR(36) NULL,
  operation_key VARCHAR(255) NOT NULL,
  operation_id VARCHAR(255) NULL,
  method ENUM('GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS', 'TRACE') NOT NULL,
  path VARCHAR(1024) NOT NULL,
  summary VARCHAR(512) NULL,
  description TEXT NULL,
  tags JSON NULL,
  request_schema JSON NULL,
  response_schemas JSON NULL,
  security_requirements JSON NULL,
  code_evidence JSON NULL,
  confidence DECIMAL(5,4) NULL,
  verification_status ENUM('unverified', 'verified', 'rejected') NOT NULL DEFAULT 'unverified',
  lifecycle_status ENUM('active', 'deprecated', 'removed') NOT NULL DEFAULT 'active',
  content_hash CHAR(64) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_api_operations_system_key (system_id, operation_key),
  UNIQUE KEY uk_api_operations_system_id_id (system_id, id),
  KEY idx_api_operations_system_method_path (system_id, method, path(191)),
  KEY idx_api_operations_scan (system_id, scan_run_id),
  KEY idx_api_operations_verification (system_id, verification_status, updated_at),
  CONSTRAINT chk_api_operations_confidence CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  CONSTRAINT fk_api_operations_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_api_operations_scan FOREIGN KEY (system_id, scan_run_id) REFERENCES scan_runs (system_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_discoveries (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  code_source_id CHAR(36) NULL,
  discovery_type ENUM('code', 'prd', 'prompt', 'mixed') NOT NULL,
  name VARCHAR(255) NOT NULL,
  input_document JSON NOT NULL,
  config JSON NULL,
  status ENUM('queued', 'running', 'ready', 'failed', 'cancelled') NOT NULL DEFAULT 'queued',
  summary JSON NULL,
  error_message TEXT NULL,
  requested_by CHAR(36) NOT NULL,
  started_at DATETIME(3) NULL,
  finished_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenario_discoveries_system_id_id (system_id, id),
  KEY idx_scenario_discoveries_system_status_created (system_id, status, created_at),
  KEY idx_scenario_discoveries_source_created (system_id, code_source_id, created_at),
  KEY idx_scenario_discoveries_requested_by (requested_by),
  CONSTRAINT fk_scenario_discoveries_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_discoveries_source FOREIGN KEY (system_id, code_source_id) REFERENCES code_sources (system_id, id),
  CONSTRAINT fk_scenario_discoveries_requested_by FOREIGN KEY (requested_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_imports (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  format ENUM('scenario_bundle', 'postman_2_1') NOT NULL,
  file_name VARCHAR(512) NOT NULL,
  content_hash CHAR(64) NOT NULL,
  status ENUM('uploaded', 'validating', 'ready', 'failed', 'applied') NOT NULL DEFAULT 'uploaded',
  raw_document JSON NOT NULL,
  conversion_report JSON NULL,
  error_message TEXT NULL,
  imported_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenario_imports_system_hash (system_id, content_hash),
  UNIQUE KEY uk_scenario_imports_system_id_id (system_id, id),
  KEY idx_scenario_imports_system_status (system_id, status, created_at),
  KEY idx_scenario_imports_imported_by (imported_by),
  CONSTRAINT fk_scenario_imports_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_imports_user FOREIGN KEY (imported_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenarios (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  scenario_key VARCHAR(128) NOT NULL,
  name VARCHAR(255) NOT NULL,
  description TEXT NULL,
  status ENUM('draft', 'active', 'archived') NOT NULL DEFAULT 'draft',
  current_version_id CHAR(36) NULL,
  created_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenarios_system_key (system_id, scenario_key),
  UNIQUE KEY uk_scenarios_system_id_id (system_id, id),
  KEY idx_scenarios_system_status (system_id, status, updated_at),
  KEY idx_scenarios_created_by (created_by),
  CONSTRAINT fk_scenarios_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenarios_created_by FOREIGN KEY (created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_versions (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  scenario_id CHAR(36) NOT NULL,
  version_no INT UNSIGNED NOT NULL,
  source_type ENUM('manual', 'generated', 'scenario_bundle', 'postman_2_1') NOT NULL,
  scenario_import_id CHAR(36) NULL,
  bundle_document JSON NOT NULL,
  change_note VARCHAR(512) NULL,
  created_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenario_versions_scenario_no (system_id, scenario_id, version_no),
  UNIQUE KEY uk_scenario_versions_system_id_id (system_id, id),
  KEY idx_scenario_versions_import (system_id, scenario_import_id),
  KEY idx_scenario_versions_created_by (created_by),
  CONSTRAINT fk_scenario_versions_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_versions_scenario FOREIGN KEY (system_id, scenario_id) REFERENCES scenarios (system_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_versions_import FOREIGN KEY (system_id, scenario_import_id) REFERENCES scenario_imports (system_id, id),
  CONSTRAINT fk_scenario_versions_created_by FOREIGN KEY (created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

ALTER TABLE scenarios
  ADD CONSTRAINT fk_scenarios_current_version
  FOREIGN KEY (system_id, current_version_id) REFERENCES scenario_versions (system_id, id);

CREATE TABLE scenario_steps (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  scenario_version_id CHAR(36) NOT NULL,
  step_key VARCHAR(128) NOT NULL,
  name VARCHAR(255) NOT NULL,
  position INT UNSIGNED NOT NULL,
  step_type ENUM('http', 'script', 'delay') NOT NULL DEFAULT 'http',
  api_operation_id CHAR(36) NULL,
  depends_on JSON NULL,
  request_config JSON NULL,
  extractors JSON NULL,
  assertions JSON NULL,
  timeout_ms INT UNSIGNED NOT NULL DEFAULT 30000,
  failure_policy ENUM('stop', 'continue') NOT NULL DEFAULT 'stop',
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenario_steps_version_key (system_id, scenario_version_id, step_key),
  UNIQUE KEY uk_scenario_steps_version_position (system_id, scenario_version_id, position),
  UNIQUE KEY uk_scenario_steps_system_id_id (system_id, id),
  KEY idx_scenario_steps_api (system_id, api_operation_id),
  CONSTRAINT chk_scenario_steps_timeout CHECK (timeout_ms > 0),
  CONSTRAINT fk_scenario_steps_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_steps_version FOREIGN KEY (system_id, scenario_version_id) REFERENCES scenario_versions (system_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_steps_api FOREIGN KEY (system_id, api_operation_id) REFERENCES api_operations (system_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_candidates (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  discovery_id CHAR(36) NOT NULL,
  candidate_key VARCHAR(128) NOT NULL,
  name VARCHAR(255) NOT NULL,
  description TEXT NULL,
  confidence DECIMAL(5,4) NULL,
  evidence JSON NOT NULL,
  candidate_bundle JSON NOT NULL,
  review_status ENUM('pending', 'accepted', 'rejected') NOT NULL DEFAULT 'pending',
  review_note TEXT NULL,
  reviewed_by CHAR(36) NULL,
  reviewed_at DATETIME(3) NULL,
  promoted_scenario_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenario_candidates_discovery_key (system_id, discovery_id, candidate_key),
  UNIQUE KEY uk_scenario_candidates_system_id_id (system_id, id),
  KEY idx_scenario_candidates_system_review (system_id, review_status, updated_at),
  KEY idx_scenario_candidates_promoted (system_id, promoted_scenario_id),
  KEY idx_scenario_candidates_reviewed_by (reviewed_by),
  CONSTRAINT chk_scenario_candidates_confidence CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  CONSTRAINT fk_scenario_candidates_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_candidates_discovery FOREIGN KEY (system_id, discovery_id) REFERENCES scenario_discoveries (system_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_candidates_scenario FOREIGN KEY (system_id, promoted_scenario_id) REFERENCES scenarios (system_id, id),
  CONSTRAINT fk_scenario_candidates_reviewer FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE environments (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  environment_key VARCHAR(64) NOT NULL,
  name VARCHAR(128) NOT NULL,
  variables JSON NULL,
  status ENUM('active', 'disabled') NOT NULL DEFAULT 'active',
  created_by CHAR(36) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_environments_system_key (system_id, environment_key),
  UNIQUE KEY uk_environments_system_id_id (system_id, id),
  KEY idx_environments_created_by (created_by),
  CONSTRAINT fk_environments_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_environments_created_by FOREIGN KEY (created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE connectors (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  environment_id CHAR(36) NOT NULL,
  connector_key VARCHAR(64) NOT NULL,
  name VARCHAR(128) NOT NULL,
  connector_type ENUM('http', 'mysql', 'redis', 'custom') NOT NULL DEFAULT 'http',
  base_url VARCHAR(2048) NULL,
  config JSON NULL,
  secret_ref VARCHAR(255) NULL,
  status ENUM('active', 'disabled') NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_connectors_environment_key (system_id, environment_id, connector_key),
  UNIQUE KEY uk_connectors_system_id_id (system_id, id),
  KEY idx_connectors_system_type (system_id, connector_type, status),
  CONSTRAINT fk_connectors_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_connectors_environment FOREIGN KEY (system_id, environment_id) REFERENCES environments (system_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_runs (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  scenario_id CHAR(36) NOT NULL,
  scenario_version_id CHAR(36) NOT NULL,
  environment_id CHAR(36) NOT NULL,
  status ENUM('queued', 'running', 'passed', 'failed', 'cancelled', 'timed_out') NOT NULL DEFAULT 'queued',
  trigger_type ENUM('manual', 'api', 'schedule') NOT NULL DEFAULT 'manual',
  input_variables JSON NULL,
  output_variables JSON NULL,
  summary JSON NULL,
  requested_by CHAR(36) NOT NULL,
  started_at DATETIME(3) NULL,
  finished_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_scenario_runs_system_id_id (system_id, id),
  KEY idx_scenario_runs_system_status_created (system_id, status, created_at),
  KEY idx_scenario_runs_scenario_created (system_id, scenario_id, created_at),
  KEY idx_scenario_runs_environment_created (system_id, environment_id, created_at),
  KEY idx_scenario_runs_requested_by (requested_by),
  CONSTRAINT fk_scenario_runs_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_scenario_runs_scenario FOREIGN KEY (system_id, scenario_id) REFERENCES scenarios (system_id, id),
  CONSTRAINT fk_scenario_runs_version FOREIGN KEY (system_id, scenario_version_id) REFERENCES scenario_versions (system_id, id),
  CONSTRAINT fk_scenario_runs_environment FOREIGN KEY (system_id, environment_id) REFERENCES environments (system_id, id),
  CONSTRAINT fk_scenario_runs_requested_by FOREIGN KEY (requested_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_step_runs (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  scenario_run_id CHAR(36) NOT NULL,
  scenario_step_id CHAR(36) NOT NULL,
  attempt_no INT UNSIGNED NOT NULL DEFAULT 1,
  position INT UNSIGNED NOT NULL,
  status ENUM('pending', 'running', 'passed', 'failed', 'skipped', 'timed_out') NOT NULL DEFAULT 'pending',
  request_snapshot JSON NULL,
  response_snapshot JSON NULL,
  extracted_variables JSON NULL,
  error_message TEXT NULL,
  duration_ms INT UNSIGNED NULL,
  started_at DATETIME(3) NULL,
  finished_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_step_runs_run_step_attempt (system_id, scenario_run_id, scenario_step_id, attempt_no),
  UNIQUE KEY uk_step_runs_system_id_id (system_id, id),
  KEY idx_step_runs_run_position (system_id, scenario_run_id, position),
  KEY idx_step_runs_status (system_id, status, created_at),
  CONSTRAINT fk_step_runs_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_step_runs_run FOREIGN KEY (system_id, scenario_run_id) REFERENCES scenario_runs (system_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_step_runs_step FOREIGN KEY (system_id, scenario_step_id) REFERENCES scenario_steps (system_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE scenario_assertion_results (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  step_run_id CHAR(36) NOT NULL,
  assertion_key VARCHAR(128) NOT NULL,
  assertion_type VARCHAR(64) NOT NULL,
  status ENUM('passed', 'failed', 'skipped', 'error') NOT NULL,
  expected_value JSON NULL,
  actual_value JSON NULL,
  message TEXT NULL,
  duration_ms INT UNSIGNED NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_assertions_step_key (system_id, step_run_id, assertion_key),
  KEY idx_assertions_step_status (system_id, step_run_id, status),
  CONSTRAINT fk_assertions_system FOREIGN KEY (system_id) REFERENCES business_systems (id) ON DELETE CASCADE,
  CONSTRAINT fk_assertions_step_run FOREIGN KEY (system_id, step_run_id) REFERENCES scenario_step_runs (system_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE audit_logs (
  id CHAR(36) NOT NULL,
  system_id CHAR(36) NOT NULL,
  actor_user_id CHAR(36) NULL,
  action VARCHAR(128) NOT NULL,
  resource_type VARCHAR(64) NOT NULL,
  resource_id CHAR(36) NULL,
  request_id VARCHAR(128) NULL,
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(512) NULL,
  before_data JSON NULL,
  after_data JSON NULL,
  metadata JSON NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_audit_logs_system_created (system_id, created_at),
  KEY idx_audit_logs_resource (system_id, resource_type, resource_id, created_at),
  KEY idx_audit_logs_actor (actor_user_id, created_at),
  KEY idx_audit_logs_request (request_id),
  CONSTRAINT fk_audit_logs_system FOREIGN KEY (system_id) REFERENCES business_systems (id),
  CONSTRAINT fk_audit_logs_actor FOREIGN KEY (actor_user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
